#else
#define debug(...)
#define debugArr(...)
#endif
const int MOD = 1000000007;

int main(){
    ios::sync_with_stdio(false);
    cin.tie(0);

    long long m, n;
    int k;
    cin >> m >> n >> k;
    vector<long long> xs(k), ys(k);
    for(int i = 0; i < k; i++){
        cin >> xs[i] >> ys[i];
    }

    long long ans = 0;
    int mask_ = 1 << k;
    vector<long long> rmin(mask_), rmax(mask_), cmin(mask_), cmax(mask_);

    rmin[0] = m+1;  rmax[0] = 0;
    cmin[0] = n+1;  cmax[0] = 0;

    for(int mask = 1; mask < mask_; mask++){
        int b = __builtin_ctz(mask);           
        int prev = mask ^ (1<<b);              

        rmin[mask] = min(rmin[prev], xs[b]);
        rmax[mask] = max(rmax[prev], xs[b]);
        cmin[mask] = min(cmin[prev], ys[b]);
        cmax[mask] = max(cmax[prev], ys[b]);

        int pc = __builtin_popcount(mask);

        long long ways_row = (rmin[mask] % MOD) * ((m+1 - rmax[mask]) % MOD) % MOD;
        long long ways_col = (cmin[mask] % MOD) * ((n+1 - cmax[mask]) % MOD) % MOD;
        long long f = ways_row * ways_col % MOD;

        if(pc & 1) {
            ans = (ans + f) % MOD;
        } else {
            ans = (ans - f + MOD) % MOD;
        }
    }

    cout << ans << "\n";
}